private static boolean isIntegral(JsonPrimitive primitive) {
  if (primitive.value instanceof Number) {
    Number number = (Number) primitive.value;
    return number instanceof BigInteger || number instanceof Long || number instanceof Integer
        || number instanceof Short || number instanceof Byte;
  }
  return false;
}

/**
 * Converts the given integral number to a {@link BigInteger}, without
 * truncating values which do not fit into a {@code long}.
 */
private static BigInteger toBigInteger(Object value, Class<?> unwrapped) {
  if (unwrapped == long.class) {
    return BigInteger.valueOf(((Number) value).longValue());
  }
  return new BigInteger(value.toString());
}

